-- Create Users table (PostgreSQL version)
DROP TABLE IF EXISTS users CASCADE;
CREATE TABLE users (
    user_id SERIAL PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL,
    email VARCHAR(255) UNIQUE NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    conversation_history JSONB DEFAULT '[]'
);

-- Create Movies table
DROP TABLE IF EXISTS movies CASCADE;
CREATE TABLE movies (
    movie_id INTEGER PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    release_year NUMERIC(5,1),
    genre VARCHAR(255),
    director VARCHAR(255),
    budget BIGINT,
    runtime NUMERIC(5,1),
    vote_average NUMERIC(3,1)
);

-- Create WatchedMovies junction table
DROP TABLE IF EXISTS watched_movies CASCADE;
CREATE TABLE watched_movies (
    watch_id SERIAL PRIMARY KEY,
    user_id INTEGER REFERENCES users(user_id) ON DELETE CASCADE,
    movie_id INTEGER REFERENCES movies(movie_id) ON DELETE CASCADE,
    rating INTEGER CHECK (rating BETWEEN 1 AND 10),
    watch_date DATE DEFAULT CURRENT_DATE,
    notes TEXT,
    UNIQUE(user_id, movie_id)  -- Prevent duplicate entries
);

